 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>Notification Preferences</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --panel: #121a2f;
       --panel-2: #17213a;
       --text: #e8ecf7;
       --muted: #9aa7c2;
       --accent: #7c8cff;
