       border: 1px solid var(--border);
       border-radius: 18px;
       padding: 22px;
     }

     .question {
       margin: 0 0 16px;
       font-size: 1.05rem;
       font-weight: 600;
     }

     .options {
       display: grid;
       gap: 12px;
       margin: 0;
       padding: 0;
       border: 0;
     }

     .option {
       display: flex;
       align-items: center;
       gap: 12px;
       padding: 14px 16px;
       border-radius: 14px;
       background: var(--panel-2);
       border: 1px solid transparent;
       transition: border-color 160ms ease, transform 160ms ease, background 160ms ease;
       cursor: pointer;
     }

