       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 12px 18px;
       font: inherit;
       font-weight: 600;
       color: #09101f;
       background: linear-gradient(135deg, var(--accent), var(--accent-2));
       cursor: pointer;
       box-shadow: 0 10px 24px rgba(124, 140, 255, 0.25);
       transition: transform 160ms ease, filter 160ms ease;
     }

     button:hover {
       transform: translateY(-1px);
       filter: brightness(1.03);
     }

