 </head>
 <body>
   <main class="card">
     <h1>Notification Preferences</h1>
     <p>Choose the single channel you prefer for receiving updates.</p>

     <form id="notification-form" novalidate>
       <div class="form-field">
         <div class="question" id="notification-question">
           How do you prefer to receive notifications?
         </div>

         <fieldset class="options" aria-labelledby="notification-question">
           <label class="option">
             <input type="radio" name="notification" value="Email" />
             <span>Email</span>
           </label>
           <label class="option">
             <input type="radio" name="notification" value="SMS" />
             <span>SMS</span>
           </label>
           <label class="option">
             <input type="radio" name="notification" value="Push Notifications" />
             <span>Push Notifications</span>
           </label>
         </fieldset>
       </div>

       <div class="actions">
         <button type="submit">Submit</button>
       </div>

       <div class="status" id="status" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const form = document.getElementById("notification-form");
     const status = document.getElementById("status");

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const selected = form.querySelector('input[name="notification"]:checked');

       if (!selected) {
         status.textContent = "Please select one notification preference.";
         return;
       }

       status.textContent = `You selected: ${selected.value}`;
     });
   </script>
 </body>
